<?php

namespace App\Repository;

use App\Entity\Utilisateur;
use Symfony\Bridge\Doctrine\Security\User\UserLoaderInterface;
use Symfony\Component\Security\Core\User\PasswordAuthenticatedUserInterface;
use Symfony\Component\Security\Core\User\PasswordUpgraderInterface;
use Symfony\Component\Security\Core\User\UserInterface;
use SortDirection;

/**
 * UtilisateurRepository
 *
 * This class was generated by the Doctrine ORM. Add your own custom
 * repository methods below.
 */
class UtilisateurRepository extends \Doctrine\ORM\EntityRepository implements UserLoaderInterface, PasswordUpgraderInterface
{
    //Connexion par identifiant ou par adresse e-mail
    public function loadUserByIdentifier(string $identifier): ?UserInterface
    {
        $identifiant = Utilisateur::canonicaliser($identifier);

        if (preg_match('/^.+\@\S+\.\S+$/', $identifiant)) {
            $utilisateur = $this->findOneBy(['emailCanonical' => $identifiant]);
            if ($utilisateur) {
                return $utilisateur;
            }
        }

        return $this->findOneBy(['usernameCanonical' => $identifiant]);
    }

    //Nouveau hachage du mot de passe quand l'algorithme évolue
    public function upgradePassword(PasswordAuthenticatedUserInterface $user, string $newHashedPassword): void
    {
        if (!$user instanceof Utilisateur) {
            return;
        }

        $user->setPassword($newHashedPassword);
        $this->getEntityManager()->flush();
    }

    public function getUtilisateursAvecRole($role){
        $qb = $this
            ->createQueryBuilder('u')
            ->where('u.roles LIKE :role')
            ->setParameter('role', '%"' . $role . '"%');

        return $qb->getQuery()->getResult();
    }

    public function triDateDerniereConnexion(){
        $qb = $this
            ->createQueryBuilder('u')
            ->orderBy('u.lastLogin', SortDirection::Descending);

        return $qb->getQuery()->getResult();
    }
}
